public ProdId parmProdIdManualSelected(ProdId _prodIdManualSelected = prodIdManualSelected)
{
    prodIdManualSelected = _prodIdManualSelected;
    return prodIdManualSelected;
}

/// <summary>
/// PaffH 02.05.24
/// </summary>
/// <param name = "_args">NDXManualPALabelArgs</param>
/// <returns>Args</returns>
public Args parmArgs(NDXManualPALabelArgs _args = args)
{
    args = _args;
    return args;
}

/// <summary>
/// PaffH 02.05.24
/// </summary>
/// <returns>formName</returns>
public formName formName()
{
    return formStr(NDXManualPALabelWizard);
}

/// <summary>
/// PaffH 02.05.24
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    NDXManualPALabelWizard wizard = new NDXManualPALabelWizard();
    _args.parmObject(NDXManualPALabelArgs::newFromArgs(_args));

    if (_args.dataset() == tableNum(InventTable))
    {
        InventTable locInventTable = _args.record();
        wizard.parmInventTable(locInventTable);
    }

    if (wizard.prompt())
    {
        wizard.run();
    }
}

/// <summary>
/// PaffH 02.05.24
/// modified: 17.10.24
/// </summary>
/// <param name = "_nDXProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <returns>NDXProdIdentControlPanel</returns>
public NDXProdIdentControlPanel parmNDXProdIdentControlPanel(NDXProdIdentControlPanel _nDXProdIdentControlPanel = nDXProdIdentControlPanel)
{
    nDXProdIdentControlPanel = _nDXProdIdentControlPanel;
    if (!nDXProdIdentControlPanel)
    {
        if (nDXProdIdentControlPanelList.elements() > 0)
        {
            ListEnumerator enum = nDXProdIdentControlPanelList.getEnumerator();
            while (enum.moveNext())
            {
                nDXProdIdentControlPanel = enum.current();
                break;
            }
        }
    }
    return nDXProdIdentControlPanel;
}

/// <summary>
/// PaffH 15.10.24
/// </summary>
public void initializeNDXProdIdentControlPanelList()
{
    nDXProdIdentControlPanelList = new List(Types::Record);
}

/// <summary>
/// PaffH 15.10.24
/// </summary>
/// <returns>nDXProdIdentControlPanelList</returns>
public List parmNDXProdIdentControlPanelList()
{
    return nDXProdIdentControlPanelList;
}

/// <summary>
/// PaffH 02.05.24
/// save NDXProdIdentControlPanel record onPrem
/// </summary>
/// <returns>NDXProdIdentControlPanelContract</returns>
//public Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract getData()
public List getData()
{
    NDXAzureRelayTransferPALabel nDXAzureRelayTransferPALabel = NDXAzureRelayTransferPALabel::construct();

    return nDXAzureRelayTransferPALabel
        .initializeAzureRelay(nDXAzureRelayTransferPALabel.parmMaintainRelayContract())
        .addContractFromNDXProdIdentControlPanel(nDXProdIdentControlPanelList)
        .getProdIdentControlPanelLines();
}

/// <summary>
/// PaffH 02.05.24
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <returns>InventTable</returns>
public InventTable parmInventTable(InventTable _inventTable = InventTable)
{
    inventTable = _inventTable;
    return inventTable;
}
